// TH14 v1.00b St4 midboss nonspell 2 (st04mbs.ecl.txt MBoss2, lines 188-235).
//
// Source clock: timerReset() at L195 is T0; L217 wait(120) + L222 wait(60) put the first
// volley at T=180; setInterrupt(0,0,1800,"MBossDead") at L214 ends the segment at T=1800.
// Card clock: frame 0 = phase begin, 120-frame opening buffer before source T0, so the
// native timeout lands near card frame 1923 and TIME_LIMIT=2424 keeps the tail budget.
//
// Shared enemy slots owned by this card: int slot 0 = next moveRand step, fx slots 0/1 =
// logical unit direction of the current moveRand step (not source I/F slots).

const TIME_LIMIT: int = 2424;
const OPENING_BUFFER: int = 120;

// TH14 native type 42 -> TH14_REST, native type 40 -> TH14_NOTE_YELLOW (bullet-types.md).
const TH14_NOTE_YELLOW: int = 1008;
const TH14_REST: int = 1040;

const RAND_SPEED: fx = 0.4fx;  // L230 moveRand(60, 4, 0.4f)

// L255-257 EX chain on emitter 0: ANIM a=1 (birth shift folded into sh_dist below),
// WAIT a=40, VELTIME 0x200000 (a=40, r=1.0, s=-999999 keeps the angle).
xformdef REST_SLOWDOWN {
    wait(40);
    step_speed(1fx, 40);
}

// --- moveRand recipe (TH16 movement.md, TH18 BossCard1 sample re-used for TH14) ---------
// Limits from the MBoss common entry moveLimit(0, 128, 280, 64): x in [-140,140],
// y in [96,160]; the native direction inner zone is x +-70, y 112..144.

sub move_step_arm() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = ((60 - k) as fx) * RAND_SPEED / 60fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub move_begin(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    move_step_arm();
}

sub move_rand_direction() {
    // Native 405b90: signed unit random * pi, kept as unwrapped BAM ints.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +-pi/2 guard, epsilon 0.05 rad = 522 BAM (normal angle quantization).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    move_begin(a as angle);
}

sub move_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        move_step_arm();
    }
}

// --- MBoss2_at: fixed-direction ring, 40 (E) / 80 (N,H,L) bullets, 200-frame period ------
async sub boss_at() {
    var n: int = 40;
    if global(GVAR_RANK) != RANK_EASY { n = 80; }

    sh_reset(0);
    sh_sprite(0, TH14_REST, 1);      // L242 etSprite(0, 42, 1)
    sh_ring(0, 1);                   // L241 etAim(0, 3): fixed-direction ring
    sh_aim(0, 0);
    sh_count(0, n, 1);               // L243-252 etCount(0, 40/80, 1)
    sh_angle(0, 90deg, 0deg);        // L253 etAngle(0, pi/2, .0327); M=1 never uses delta
    sh_speed(0, 3fx, 0fx);           // L254 etSpeed(0, 3.0, 1.0); M=1 uses s0
    sh_dist(0, 4fx);                 // L258 etDist(16) + ANIM a=1 birth shift -4*3
    sh_xform(0, REST_SLOWDOWN);

    var t: int = 0;
    while t < 1620 {                 // first volley at source T=180, stop before T=1800
        sh_fire(0);                  // L262 etOn(0)
        wait(200);                   // L263 wait(200)
        t = t + 200;
    }
}

// --- MBoss2_at2: fixed alternating-layer ring (aim mode 10), rotating base --------------
// L276-291 stack: ways [-1] = 1/1/2/2, layers [-2] = 3/5/5/8; L304-312 wait 4/3/2/2.
async sub boss_at2() {
    var rank: int = global(GVAR_RANK);
    var ways: int = 2;
    var layers: int = 8;
    var period: int = 2;
    if rank == RANK_EASY { ways = 1; layers = 3; period = 4; }
    else if rank == RANK_NORMAL { ways = 1; layers = 5; period = 3; }
    else if rank == RANK_HARD { ways = 2; layers = 5; period = 2; }

    sh_reset(0);
    sh_sprite(0, TH14_NOTE_YELLOW, 0);  // L275 etSprite(1, 40, 0)
    sh_ring(0, 1);                      // one static ring per layer keeps source layer order
    sh_aim(0, 0);
    sh_count(0, ways, 1);
    sh_speed(0, 2.4fx, 0fx);            // L295 etSpeed(1, 2.4, 2.4): every layer 2.4
    sh_dist(0, 6.4fx);                  // L297 etDist(16) + ANIM a=1 birth shift -4*2.4

    var a0: int = 0;
    var t: int = 0;
    while t < 1620 {
        for q in 0..layers {
            // L274 etAim(1, 10): alpha + (-1)^q * (R(i) + H(layers,q)), H step 10deg.
            var h: int = ((q + 1) / 2) * 1820;
            if layers % 2 == 0 { h = (q / 2) * 1820 + 910; }
            var base: int = a0 + h;
            if q % 2 != 0 { base = a0 - h; }
            sh_angle(0, base as angle, 0deg);
            sh_fire(0);                 // L302 etOn(1)
        }
        a0 = a0 + 1638;                 // L303 %A += 0.15708 rad
        wait(period);                   // L304-312 wait(4/3/2/2)
        t = t + period;
    }
}

// MBossDead timeout branch creates Ecl_EtBreak_ni (L432): etClear at radius 16, +10/frame.
async sub boss_clear_sweep(cx: fx, cy: fx) {
    var r: fx = 16fx;
    while r < 640fx {
        clear_bullets_at(cx, cy, r, 0);
        r = r + 10fx;
        wait(1);                        // L153 goto @1: one radius step per frame
    }
}

async sub boss_main() {
    // MBoss common entry state: hurtbox/hitbox 48x48 -> radius 24, boss at (0,128).
    set_invuln(65535);                  // training shell: no DPS; L216 setInvuln(120) subsumed
    set_hurtbox(24fx);
    set_hitbox(24fx);
    // L196-210 cleanup: no prior async/child/laser exists in a fresh card.
    clear_bullets_at($self_x, $self_y, 640fx, 0);  // L199 etCancel(640) (TIMEOUT==0 path)
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);         // L208-209 moveVel/moveVelTime zero
    // L210 movePosTime(0,0,0,0): frames<=0 only cancels position interpolation.
    wait(120);                          // L217
    wait(60);                           // L222
    spawn boss_at();                    // L223
    spawn boss_at2();                   // L224

    // L226-233 loop: wait(60), wait(30), moveRand(60,4,0.4f), wait(70); 10 cycles end at
    // source T=1780, then 20 frames reach the native slot-0 timeout at T=1800.
    for cycle in 0..10 {
        move_wait(60);
        move_wait(30);
        move_rand_direction();
        move_wait(70);
    }
    move_wait(20);

    // MBossDead (L423-449), timeout branch; drops/anm/sound/chapter/boss UI omitted.
    spawn boss_clear_sweep($self_x, $self_y);
    wait(120);                          // L445
    move_to(60, -224fx, 64fx, EASE_QUAD_OUT);  // L446 movePosTime(60, 4, -224, 64)
    wait(60);                           // L447; L448-449 delete
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 9000, 0, 0, 0, boss_main);  // L191 lifeSet(9000)
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
